@Test
@SuppressWarnings("unchecked")
public void testSwitchClosure_1_oe() {
    final MockClosure<String> a = new MockClosure<>();
    final MockClosure<String> b = new MockClosure<>();
    ClosureUtils.<String>switchClosure(
