                return false;
            }
            return true;
        }

        @Override
        public int hash(final Integer o) {
            return o.intValue() % 2 == 0 ? Integer.valueOf(0).hashCode() : Integer.valueOf(1).hashCode();
        }
    };

    // removed other assertion
    assertTrue(CollectionUtils.isEqualCollection(collectionA, collB, e));
}

