public void testIndexedArray_1_oe() {
    Iterator<E> iter = makeArrayIterator(testArray, 2);
    int count = 0;
    while (iter.hasNext()) {
        ++count;
        iter.next();
    }

    assertEquals("the count should be right using ArrayIterator(Object,2) ", count, testArray.length - 2);
}

