public void testPermutationResultSize_1_oe() {
    int factorial = 1;
    for (int i = 0; i < 8; i++, factorial*=i) {
        final List<Integer> list = new ArrayList<>();
        for (int j = 0; j < i; j++) {
            list.add(j);
        }
        final Iterator<List<Integer>> it = new PermutationIterator<>(list);
        int count = 0;
        while (it.hasNext()) {
            it.next();
            count++;
        }
        assertEquals(factorial, count);
}
}

