public void testPrefixMapClear_1_oe() {
    final Trie<String, Integer> trie = new PatriciaTrie<>();
    trie.put("Anna", 1);
    trie.put("Anael", 2);
    trie.put("Analu", 3);
    trie.put("Andreas", 4);
    trie.put("Andrea", 5);
    trie.put("Andres", 6);
    trie.put("Anatole", 7);
