public void testGetByIndex_1_oe() {
    resetEmpty();
    LinkedMap<K, V> lm = getMap();
    try {
        lm.get(0);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lm.get(-1);
    } catch (final IndexOutOfBoundsException ex) {}

    resetFull();
    lm = getMap();
    try {
        lm.get(-1);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lm.get(lm.size());
    } catch (final IndexOutOfBoundsException ex) {}

    int i = 0;
    for (final MapIterator<K, V> it = lm.mapIterator(); it.hasNext(); i++) {
        assertSame(it.next(), lm.get(i));
}
}

